// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        address caller
    ) public {
        vm.assume(caller != c.DEPOSITOR_ACCOUNT());
        uint256 initialL1FeeScalar = c.l1FeeScalar();
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            // call succeeded; check state unchanged
            assertTrue(c.l1FeeScalar() == initialL1FeeScalar);
        } catch {
            // call reverted; state unchanged
            assertTrue(true);
        }
    }
}

